import re
from collections import defaultdict

def parse_duration(text):
    if not text:
        raise ValueError("Empty string")

    # Check for negative numbers
    if re.search(r'-', text):
        raise ValueError("Negative numbers not allowed")

    # Check for decimals
    if re.search(r'\.', text):
        raise ValueError("Decimals not allowed")

    # Check for spaces
    if ' ' in text:
        raise ValueError("Spaces not allowed")

    # Check for unknown units or out-of-order units
    pattern = r'^(\d+[dhms])*$'
    if not re.fullmatch(pattern, text):
        raise ValueError("Invalid format")

    # Check for repeated units
    units = defaultdict(int)
    for match in re.finditer(r'([dhms])', text):
        unit = match.group(1)
        if units[unit] > 0:
            raise ValueError("Repeated unit")
        units[unit] += 1

    # Check for out-of-order units
    unit_order = []
    for match in re.finditer(r'([dhms])', text):
        unit_order.append(match.group(1))

    expected_order = ['d', 'h', 'm', 's']
    for i, unit in enumerate(unit_order):
        if unit != expected_order[i]:
            raise ValueError("Units must appear in order: days, hours, minutes, seconds")

    # Parse the text into a dictionary of integers
    parts = re.findall(r'(\d+)(d|h|m|s)', text)
    duration_dict = {}
    for num, unit in parts:
        duration_dict[unit] = int(num)

    # Calculate total seconds
    total_seconds = 0
    for unit, num in duration_dict.items():
        if unit == 'd':
            total_seconds += num * 86400
        elif unit == 'h':
            total_seconds += num * 3600
        elif unit == 'm':
            total_seconds += num * 60
        elif unit == 's':
            total_seconds += num

    return total_seconds
